project_description:
Provides a Drupal cache backend for Kevinrob/guzzle-cache-middleware, so outbound HTTP responses fetched through Guzzle can be cached in a Drupal cache backend following the RFC 7234 HTTP caching model (Cache-Control, ETag, Last-Modified). The base module ships the DrupalGuzzleCache storage adapter for manual wiring onto a Guzzle HandlerStack; the guzzle_cache_middleware submodule registers it as an http_client_middleware so that all requests made through Drupal's http_client service are cached automatically.

Manual usage:

<?php
use GuzzleHttp\Client;
use GuzzleHttp\HandlerStack;
use Kevinrob\GuzzleCache\CacheMiddleware;
use Kevinrob\GuzzleCache\Strategy\PrivateCacheStrategy;
use Drupal\guzzle_cache\DrupalGuzzleCache;

$stack = HandlerStack::create();
// A dedicated cache bin is recommended so it can be managed independently.
$cache = new DrupalGuzzleCache(\Drupal::service('cache.my_custom_http_cache_bin'));
$stack->push(new CacheMiddleware(new PrivateCacheStrategy($cache)), 'cache');
$client = new Client(['handler' => $stack]);
$response = $client->request('GET', 'http://www.example.com/');
?>
